modules.breadcrumb:
.p-breadcrumb {
    background: dt('breadcrumb.background');
    padding: dt('breadcrumb.padding');
    overflow-x: auto;
}

.p-breadcrumb-list {
    margin: 0;
    padding: 0;
    list-style-type: none;
    display: flex;
    align-items: center;
    flex-wrap: nowrap;
    gap: dt('breadcrumb.gap');
}

.p-breadcrumb-separator {
    display: flex;
    align-items: center;
    color: dt('breadcrumb.separator.color');
}

.p-breadcrumb-separator-icon:dir(rtl) {
    transform: rotate(180deg);
}

.p-breadcrumb::-webkit-scrollbar {
    display: none;
}

.p-breadcrumb-item-link {
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: dt('breadcrumb.item.gap');
    transition:
        background dt('breadcrumb.transition.duration'),
        color dt('breadcrumb.transition.duration'),
        outline-color dt('breadcrumb.transition.duration'),
        box-shadow dt('breadcrumb.transition.duration');
    border-radius: dt('breadcrumb.item.border.radius');
    outline-color: transparent;
    color: dt('breadcrumb.item.color');
}

.p-breadcrumb-item-link:focus-visible {
    box-shadow: dt('breadcrumb.item.focus.ring.shadow');
    outline: dt('breadcrumb.item.focus.ring.width') dt('breadcrumb.item.focus.ring.style') dt('breadcrumb.item.focus.ring.color');
    outline-offset: dt('breadcrumb.item.focus.ring.offset');
}

.p-breadcrumb-item-link:hover .p-breadcrumb-item-label {
    color: dt('breadcrumb.item.hover.color');
}

.p-breadcrumb-item-label {
    transition: inherit;
}

.p-breadcrumb-item-icon {
    color: dt('breadcrumb.item.icon.color');
    transition: inherit;
}

.p-breadcrumb-item-link:hover .p-breadcrumb-item-icon {
    color: dt('breadcrumb.item.icon.hover.color');
}

modules.dock:
.p-dock {
    position: absolute;
    z-index: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    pointer-events: none;
}

.p-dock-list-container {
    display: flex;
    pointer-events: auto;
    background: dt('dock.background');
    border: 1px solid dt('dock.border.color');
    padding: dt('dock.padding');
    border-radius: dt('dock.border.radius');
}

.p-dock-list {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    align-items: center;
    justify-content: center;
    outline: 0 none;
}

.p-dock-item {
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    will-change: transform;
    padding: dt('dock.item.padding');
    border-radius: dt('dock.item.border.radius');
}

.p-dock-item.p-focus {
    box-shadow: dt('dock.item.focus.ring.shadow');
    outline: dt('dock.item.focus.ring.width') dt('dock.item.focus.ring.style') dt('dock.item.focus.ring.color');
    outline-offset: dt('dock.item.focus.ring.offset');
}

.p-dock-item-link {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    cursor: default;
    width: dt('dock.item.size');
    height: dt('dock.item.size');
}

.p-dock-top {
    left: 0;
    top: 0;
    width: 100%;
}

.p-dock-bottom {
    left: 0;
    bottom: 0;
    width: 100%;
}

.p-dock-right {
    right: 0;
    top: 0;
    height: 100%;
}

.p-dock-right .p-dock-list {
    flex-direction: column;
}

.p-dock-left {
    left: 0;
    top: 0;
    height: 100%;
}

.p-dock-left .p-dock-list {
    flex-direction: column;
}

.p-dock-mobile.p-dock-top .p-dock-list-container,
.p-dock-mobile.p-dock-bottom .p-dock-list-container {
    overflow-x: auto;
    width: 100%;
}

.p-dock-mobile.p-dock-top .p-dock-list-container .p-dock-list,
.p-dock-mobile.p-dock-bottom .p-dock-list-container .p-dock-list {
    margin: 0 auto;
}

.p-dock-mobile.p-dock-left .p-dock-list-container,
.p-dock-mobile.p-dock-right .p-dock-list-container {
    overflow-y: auto;
    height: 100%;
}

.p-dock-mobile.p-dock-left .p-dock-list-container .p-dock-list,
.p-dock-mobile.p-dock-right .p-dock-list-container .p-dock-list {
    margin: auto 0;
}

.p-dock-mobile .p-dock-list .p-dock-item {
    transform: none;
    margin: 0;
}

modules.steps:
.p-steps {
    position: relative;
}

.p-steps-list {
    padding: 0;
    margin: 0;
    list-style-type: none;
    display: flex;
}

.p-steps-item {
    position: relative;
    display: flex;
    justify-content: center;
    flex: 1 1 auto;
}

.p-steps-item.p-disabled,
.p-steps-item.p-disabled * {
    opacity: 1;
    pointer-events: auto;
    user-select: auto;
    cursor: auto;
}

.p-steps-item:before {
    content: ' ';
    border-top: 2px solid dt('steps.separator.background');
    width: 100%;
    top: 50%;
    left: 0;
    display: block;
    position: absolute;
    margin-top: calc(-1rem + 1px);
}

.p-steps-item:first-child::before {
    width: calc(50% + 1rem);
    transform: translateX(100%);
}

.p-steps-item:last-child::before {
    width: 50%;
}

.p-steps-item-link {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    overflow: hidden;
    text-decoration: none;
    transition:
        outline-color dt('steps.transition.duration'),
        box-shadow dt('steps.transition.duration');
    border-radius: dt('steps.item.link.border.radius');
    outline-color: transparent;
    gap: dt('steps.item.link.gap');
}

.p-steps-item-link:not(.p-disabled):focus-visible {
    box-shadow: dt('steps.item.link.focus.ring.shadow');
    outline: dt('steps.item.link.focus.ring.width') dt('steps.item.link.focus.ring.style') dt('steps.item.link.focus.ring.color');
    outline-offset: dt('steps.item.link.focus.ring.offset');
}

.p-steps-item-label {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
    color: dt('steps.item.label.color');
    display: block;
    font-weight: dt('steps.item.label.font.weight');
}

.p-steps-item-number {
    display: flex;
    align-items: center;
    justify-content: center;
    color: dt('steps.item.number.color');
    border: 2px solid dt('steps.item.number.border.color');
    background: dt('steps.item.number.background');
    min-width: dt('steps.item.number.size');
    height: dt('steps.item.number.size');
    line-height: dt('steps.item.number.size');
    font-size: dt('steps.item.number.font.size');
    z-index: 1;
    border-radius: dt('steps.item.number.border.radius');
    position: relative;
    font-weight: dt('steps.item.number.font.weight');
}

.p-steps-item-number::after {
    content: ' ';
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: dt('steps.item.number.border.radius');
    box-shadow: dt('steps.item.number.shadow');
}

.p-steps:not(.p-readonly) .p-steps-item {
    cursor: pointer;
}

.p-steps-item-active .p-steps-item-number {
    background: dt('steps.item.number.active.background');
    border-color: dt('steps.item.number.active.border.color');
    color: dt('steps.item.number.active.color');
}

.p-steps-item-active .p-steps-item-label {
    color: dt('steps.item.label.active.color');
}

modules.stepper:
.p-steplist {
    position: relative;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 0;
    padding: 0;
    list-style-type: none;
    overflow-x: auto;
}

.p-step {
    position: relative;
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    gap: dt('stepper.step.gap');
    padding: dt('stepper.step.padding');
}

.p-step:last-of-type {
    flex: initial;
}

.p-step-header {
    border: 0 none;
    display: inline-flex;
    align-items: center;
    text-decoration: none;
    cursor: pointer;
    transition:
        background dt('stepper.transition.duration'),
        color dt('stepper.transition.duration'),
        border-color dt('stepper.transition.duration'),
        outline-color dt('stepper.transition.duration'),
        box-shadow dt('stepper.transition.duration');
    border-radius: dt('stepper.step.header.border.radius');
    outline-color: transparent;
    background: transparent;
    padding: dt('stepper.step.header.padding');
    gap: dt('stepper.step.header.gap');
}

.p-step-header:focus-visible {
    box-shadow: dt('stepper.step.header.focus.ring.shadow');
    outline: dt('stepper.step.header.focus.ring.width') dt('stepper.step.header.focus.ring.style') dt('stepper.step.header.focus.ring.color');
    outline-offset: dt('stepper.step.header.focus.ring.offset');
}

.p-stepper.p-stepper-readonly .p-step {
    cursor: auto;
}

.p-step-title {
    display: block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
    color: dt('stepper.step.title.color');
    font-weight: dt('stepper.step.title.font.weight');
    transition:
        background dt('stepper.transition.duration'),
        color dt('stepper.transition.duration'),
        border-color dt('stepper.transition.duration'),
        box-shadow dt('stepper.transition.duration'),
        outline-color dt('stepper.transition.duration');
}

.p-step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    color: dt('stepper.step.number.color');
    border: 2px solid dt('stepper.step.number.border.color');
    background: dt('stepper.step.number.background');
    min-width: dt('stepper.step.number.size');
    height: dt('stepper.step.number.size');
    line-height: dt('stepper.step.number.size');
    font-size: dt('stepper.step.number.font.size');
    z-index: 1;
    border-radius: dt('stepper.step.number.border.radius');
    position: relative;
    font-weight: dt('stepper.step.number.font.weight');
}

.p-step-number::after {
    content: ' ';
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: dt('stepper.step.number.border.radius');
    box-shadow: dt('stepper.step.number.shadow');
}

.p-step-active .p-step-header {
    cursor: default;
}

.p-step-active .p-step-number {
    background: dt('stepper.step.number.active.background');
    border-color: dt('stepper.step.number.active.border.color');
    color: dt('stepper.step.number.active.color');
}

.p-step-active .p-step-title {
    color: dt('stepper.step.title.active.color');
}

.p-step:not(.p-disabled):focus-visible {
    outline: dt('focus.ring.width') dt('focus.ring.style') dt('focus.ring.color');
    outline-offset: dt('focus.ring.offset');
}

.p-step:has(~ .p-step-active) .p-stepper-separator {
    background: dt('stepper.separator.active.background');
}

.p-stepper-separator {
    flex: 1 1 0;
    background: dt('stepper.separator.background');
    width: 100%;
    height: dt('stepper.separator.size');
    transition:
        background dt('stepper.transition.duration'),
        color dt('stepper.transition.duration'),
        border-color dt('stepper.transition.duration'),
        box-shadow dt('stepper.transition.duration'),
        outline-color dt('stepper.transition.duration');
}

.p-steppanels {
    padding: dt('stepper.steppanels.padding');
}

.p-steppanel {
    background: dt('stepper.steppanel.background');
    color: dt('stepper.steppanel.color');
}

.p-stepper:has(.p-stepitem) {
    display: flex;
    flex-direction: column;
}

.p-stepitem {
    display: flex;
    flex-direction: column;
    flex: initial;
}

.p-stepitem.p-stepitem-active {
    flex: 1 1 auto;
}

.p-stepitem .p-step {
    flex: initial;
}

.p-stepitem .p-steppanel {
    display: grid;
    grid-template-rows: 1fr;
}

.p-stepitem .p-steppanel-content-wrapper {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
}
.p-stepitem .p-steppanel-content {
    width: 100%;
    padding: dt('stepper.steppanel.padding');
    margin-inline-start: 1rem;
}

.p-stepitem .p-stepper-separator {
    flex: 0 0 auto;
    width: dt('stepper.separator.size');
    height: auto;
    margin: dt('stepper.separator.margin');
    position: relative;
    left: calc(-1 * dt('stepper.separator.size'));
}

.p-stepitem .p-stepper-separator:dir(rtl) {
    left: calc(-9 * dt('stepper.separator.size'));
}

.p-stepitem:has(~ .p-stepitem-active) .p-stepper-separator {
    background: dt('stepper.separator.active.background');
}

.p-stepitem:last-of-type .p-steppanel {
    padding-inline-start: dt('stepper.step.number.size');
}

modules.tabs:
.p-tabs {
    display: flex;
    flex-direction: column;
}

.p-tablist {
    display: flex;
    position: relative;
    overflow: hidden;
    background: dt('tabs.tablist.background');
}

.p-tablist-viewport {
    overflow-x: auto;
    overflow-y: hidden;
    scroll-behavior: smooth;
    scrollbar-width: none;
    overscroll-behavior: contain auto;
}

.p-tablist-viewport::-webkit-scrollbar {
    display: none;
}

.p-tablist-tab-list {
    position: relative;
    display: flex;
    border-style: solid;
    border-color: dt('tabs.tablist.border.color');
    border-width: dt('tabs.tablist.border.width');
}

.p-tablist-content {
    flex-grow: 1;
}

.p-tablist-nav-button {
    all: unset;
    position: absolute !important;
    flex-shrink: 0;
    inset-block-start: 0;
    z-index: 2;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: dt('tabs.nav.button.background');
    color: dt('tabs.nav.button.color');
    width: dt('tabs.nav.button.width');
    transition:
        color dt('tabs.transition.duration'),
        outline-color dt('tabs.transition.duration'),
        box-shadow dt('tabs.transition.duration');
    box-shadow: dt('tabs.nav.button.shadow');
    outline-color: transparent;
    cursor: pointer;
}

.p-tablist-nav-button:focus-visible {
    z-index: 1;
    box-shadow: dt('tabs.nav.button.focus.ring.shadow');
    outline: dt('tabs.nav.button.focus.ring.width') dt('tabs.nav.button.focus.ring.style') dt('tabs.nav.button.focus.ring.color');
    outline-offset: dt('tabs.nav.button.focus.ring.offset');
}

.p-tablist-nav-button:hover {
    color: dt('tabs.nav.button.hover.color');
}

.p-tablist-prev-button {
    inset-inline-start: 0;
}

.p-tablist-next-button {
    inset-inline-end: 0;
}

.p-tablist-prev-button:dir(rtl),
.p-tablist-next-button:dir(rtl) {
    transform: rotate(180deg);
}

.p-tab {
    flex-shrink: 0;
    cursor: pointer;
    user-select: none;
    position: relative;
    border-style: solid;
    white-space: nowrap;
    gap: dt('tabs.tab.gap');
    background: dt('tabs.tab.background');
    border-width: dt('tabs.tab.border.width');
    border-color: dt('tabs.tab.border.color');
    color: dt('tabs.tab.color');
    padding: dt('tabs.tab.padding');
    font-weight: dt('tabs.tab.font.weight');
    transition:
        background dt('tabs.transition.duration'),
        border-color dt('tabs.transition.duration'),
        color dt('tabs.transition.duration'),
        outline-color dt('tabs.transition.duration'),
        box-shadow dt('tabs.transition.duration');
    margin: dt('tabs.tab.margin');
    outline-color: transparent;
}

.p-tab:not(.p-disabled):focus-visible {
    z-index: 1;
    box-shadow: dt('tabs.tab.focus.ring.shadow');
    outline: dt('tabs.tab.focus.ring.width') dt('tabs.tab.focus.ring.style') dt('tabs.tab.focus.ring.color');
    outline-offset: dt('tabs.tab.focus.ring.offset');
}

.p-tab:not(.p-tab-active):not(.p-disabled):hover {
    background: dt('tabs.tab.hover.background');
    border-color: dt('tabs.tab.hover.border.color');
    color: dt('tabs.tab.hover.color');
}

.p-tab-active {
    background: dt('tabs.tab.active.background');
    border-color: dt('tabs.tab.active.border.color');
    color: dt('tabs.tab.active.color');
}

.p-tabpanels {
    background: dt('tabs.tabpanel.background');
    color: dt('tabs.tabpanel.color');
    padding: dt('tabs.tabpanel.padding');
    outline: 0 none;
}

.p-tabpanel:focus-visible {
    box-shadow: dt('tabs.tabpanel.focus.ring.shadow');
    outline: dt('tabs.tabpanel.focus.ring.width') dt('tabs.tabpanel.focus.ring.style') dt('tabs.tabpanel.focus.ring.color');
    outline-offset: dt('tabs.tabpanel.focus.ring.offset');
}

.p-tablist-active-bar {
    z-index: 1;
    display: block;
    position: absolute;
    inset-block-end: dt('tabs.active.bar.bottom');
    height: dt('tabs.active.bar.height');
    background: dt('tabs.active.bar.background');
    transition: 250ms cubic-bezier(0.35, 0, 0.25, 1);
}

modules.base:
*,
::before,
::after {
    box-sizing: border-box;
}

.p-collapsible-enter-active {
    animation: p-animate-collapsible-expand 0.2s ease-out;
    overflow: hidden;
}

.p-collapsible-leave-active {
    animation: p-animate-collapsible-collapse 0.2s ease-out;
    overflow: hidden;
}

@keyframes p-animate-collapsible-expand {
    from {
        grid-template-rows: 0fr;
    }
    to {
        grid-template-rows: 1fr;
    }
}

@keyframes p-animate-collapsible-collapse {
    from {
        grid-template-rows: 1fr;
    }
    to {
        grid-template-rows: 0fr;
    }
}

.p-disabled,
.p-disabled * {
    cursor: default;
    pointer-events: none;
    user-select: none;
}

.p-disabled,
.p-component:disabled {
    opacity: dt('disabled.opacity');
}

.pi {
    font-size: dt('icon.size');
}

.p-icon {
    width: dt('icon.size');
    height: dt('icon.size');
}

.p-overlay-mask {
    background: var(--px-mask-background, dt('mask.background'));
    color: dt('mask.color');
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.p-overlay-mask-enter-active {
    animation: p-animate-overlay-mask-enter dt('mask.transition.duration') forwards;
}

.p-overlay-mask-leave-active {
    animation: p-animate-overlay-mask-leave dt('mask.transition.duration') forwards;
}

@keyframes p-animate-overlay-mask-enter {
    from {
        background: transparent;
    }
    to {
        background: var(--px-mask-background, dt('mask.background'));
    }
}
@keyframes p-animate-overlay-mask-leave {
    from {
        background: var(--px-mask-background, dt('mask.background'));
    }
    to {
        background: transparent;
    }
}

.p-anchored-overlay-enter-active {
    animation: p-animate-anchored-overlay-enter 300ms cubic-bezier(.19,1,.22,1);
}

.p-anchored-overlay-leave-active {
    animation: p-animate-anchored-overlay-leave 300ms cubic-bezier(.19,1,.22,1);
}

@keyframes p-animate-anchored-overlay-enter {
    from {
        opacity: 0;
        transform: scale(0.93);
    }
}

@keyframes p-animate-anchored-overlay-leave {
    to {
        opacity: 0;
        transform: scale(0.93);
    }
}
